class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        NEG = -10**15                     # sentinel for impossible states
        dp = [[[NEG] * 3 for _ in range(n)] for _ in range(m)]

        # starting cell
        start = coins[0][0]
        dp[0][0][0] = start
        if start < 0:
            dp[0][0][1] = 0               # neutralize the robber at start

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                val = coins[i][j]
                for k in range(3):
                    # transition without using a new neutralization
                    best = NEG
                    if i > 0:
                        best = max(best, dp[i - 1][j][k])
                    if j > 0:
                        best = max(best, dp[i][j - 1][k])
                    if best != NEG:
                        dp[i][j][k] = max(dp[i][j][k], best + val)

                    # transition using a neutralization on a robber cell
                    if val < 0 and k > 0:
                        best2 = NEG
                        if i > 0:
                            best2 = max(best2, dp[i - 1][j][k - 1])
                        if j > 0:
                            best2 = max(best2, dp[i][j - 1][k - 1])
                        if best2 != NEG:
                            dp[i][j][k] = max(dp[i][j][k], best2)   # robber neutralized, no coin change

        return max(dp[m - 1][n - 1])

