class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k > n:
            return -1

        # count how many subarrays of size k each integer appears in
        sub_cnt = defaultdict(int)

        # frequency of numbers in the current window
        freq = defaultdict(int)
        for i in range(k):
            freq[nums[i]] += 1

        # slide the window
        for start in range(n - k + 1):
            # every distinct number in the current window appears in this subarray
            for val in freq:
                sub_cnt[val] += 1

            # move window forward
            if start + k < n:
                left = nums[start]
                right = nums[start + k]

                freq[left] -= 1
                if freq[left] == 0:
                    del freq[left]

                freq[right] += 1

        # find the largest integer that appears in exactly one subarray
        ans = -1
        for val, cnt in sub_cnt.items():
            if cnt == 1 and val > ans:
                ans = val

        return ans

