class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        take = True  # flag to decide whether to record the current cell

        for i, row in enumerate(grid):
            if i % 2 == 0:  # left to right
                cols = range(len(row))
            else:           # right to left
                cols = range(len(row) - 1, -1, -1)

            for j in cols:
                if take:
                    result.append(grid[i][j])
                take = not take  # flip after each cell

        return result

class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        for i in range(n - k + 1):
            ch = s[i]
            # check that the substring s[i:i+k] is made of the same character
            all_same = True
            for j in range(i, i + k):
                if s[j] != ch:
                    all_same = False
                    break
            if not all_same:
                continue
            # character before the substring must be different (if it exists)
            if i > 0 and s[i - 1] == ch:
                continue
            # character after the substring must be different (if it exists)
            if i + k < n and s[i + k] == ch:
                continue
            return True
        return False

