class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Prepare a list of processed events with explicit online‑restoration events
        processed = []          # (timestamp, priority, kind, data)
        for ev in events:
            kind = ev[0]
            ts = int(ev[1])
            if kind == "OFFLINE":
                uid = int(ev[2])
                # user goes offline now
                processed.append((ts, 0, "OFFLINE", uid))
                # user comes back online after 60 time units
                processed.append((ts + 60, 0, "ONLINE", uid))
            else:  # MESSAGE
                mentions_str = ev[2]
                processed.append((ts, 1, "MESSAGE", mentions_str))

        # Sort: earlier timestamps first; for same timestamp status changes (priority 0) before messages (priority 1)
        processed.sort(key=lambda x: (x[0], x[1]))

        online = [True] * numberOfUsers          # current online status
        mentions = [0] * numberOfUsers           # result array

        for _, _, kind, data in processed:
            if kind == "OFFLINE":
                online[data] = False
            elif kind == "ONLINE":
                online[data] = True
            else:  # MESSAGE
                tokens = data.split()
                for token in tokens:
                    if token == "ALL":
                        for i in range(numberOfUsers):
                            mentions[i] += 1
                    elif token == "HERE":
                        for i in range(numberOfUsers):
                            if online[i]:
                                mentions[i] += 1
                    elif token.startswith("id"):
                        uid = int(token[2:])
                        mentions[uid] += 1
        return mentions

