    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i in range(1, n + 1):
            pref[i] = pref[i - 1] + nums[i - 1]

        INF_NEG = -10 ** 18
        dp_prev = [INF_NEG] * (n + 1)
        dp_prev[0] = 0  # 0 subarrays using 0 elements

        for sub in range(1, k + 1):
            dp_curr = [INF_NEG] * (n + 1)
            best = INF_NEG  # max of dp_prev[t] - pref[t] for t <= i-m
            for i in range(1, n + 1):
                # update best with position i-m (if allowed)
                if i - m >= 0 and dp_prev[i - m] != INF_NEG:
                    cand = dp_prev[i - m] - pref[i - m]
                    if cand > best:
                        best = cand

                # option 1: skip position i
                dp_curr[i] = dp_curr[i - 1]

                # option 2: end a subarray at i (length at least m)
                if best != INF_NEG:
                    take = pref[i] + best
                    if take > dp_curr[i]:
                        dp_curr[i] = take
            dp_prev = dp_curr

        return dp_prev[n]

