class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0
        for i in range(n):
            left = i - k
            right = i + k
            # Determine if the current element is good
            if left < 0 and right >= n:
                good = True
            elif left < 0:
                good = nums[i] > nums[right]
            elif right >= n:
                good = nums[i] > nums[left]
            else:
                good = nums[i] > nums[left] and nums[i] > nums[right]
            if good:
                total += nums[i]
        return total

