class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        # prefix sum of f(x) = number of base‑4 digits of x, for x from 1..N
        def prefix(N: int) -> int:
            if N <= 0:
                return 0
            ans = 0
            k = 1          # current digit length
            start = 1      # 4^{k-1}
            while start <= N:
                end = start * 4 - 1          # 4^{k} - 1
                cnt = min(N, end) - start + 1
                ans += k * cnt
                k += 1
                start *= 4
            return ans

        total_answer = 0
        for l, r in queries:
            total = prefix(r) - prefix(l - 1)
            ops = (total + 1) // 2
            total_answer += ops
        return total_answer

