    def maxFrequency(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total_k = sum(1 for x in nums if x == k)
        best_delta = 0

        # values are between 1 and 50 inclusive
        for v in range(1, 51):
            if v == k:
                continue
            cur = 0
            max_cur = -10**9  # sufficiently small
            for num in nums:
                if num == v:
                    w = 1
                elif num == k:
                    w = -1
                else:
                    w = 0
                cur = max(w, cur + w)
                max_cur = max(max_cur, cur)
            if max_cur > best_delta:
                best_delta = max_cur

        return total_k + best_delta

class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        x = y = 0
        ans = 0
        n = len(s)
        for i, ch in enumerate(s, 1):  # i is 1‑based step count
            if ch == 'N':
                y += 1
            elif ch == 'S':
                y -= 1
            elif ch == 'E':
                x += 1
            else:  # 'W'
                x -= 1

            cur = abs(x) + abs(y)                      # distance without changes
            allow = min(k, i)                           # we can change at most this many moves in the first i steps
            best = cur + 2 * allow                      # each change can increase distance by at most 2
            if best > i:                                # cannot exceed i (all moves in same direction)
                best = i
            if best > ans:
                ans = best
        return ans

