class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        MAX_VAL = 100000  # given constraint for values
        INF = len(elements) + 5  # larger than any possible index

        # store the smallest index for each element value
        first_idx = [INF] * (MAX_VAL + 1)
        for i, val in enumerate(elements):
            if val <= MAX_VAL and first_idx[val] == INF:
                first_idx[val] = i

        result = []
        for g in groups:
            best = INF
            d = 1
            while d * d <= g:
                if g % d == 0:
                    # divisor d
                    if d <= MAX_VAL:
                        idx = first_idx[d]
                        if idx < best:
                            best = idx
                    # counterpart divisor g//d
                    other = g // d
                    if other != d and other <= MAX_VAL:
                        idx = first_idx[other]
                        if idx < best:
                            best = idx
                d += 1
            result.append(-1 if best == INF else best)

        return result

