class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        # Helper to check if a target minimum score `val` is achievable
        def can_achieve(val: int) -> bool:
            total = 0
            for p in points:
                # minimum visits required for this position
                need = (val + p - 1) // p   # ceil division
                total += need
                if total > m:               # early stop
                    return False
            return total <= m

        max_point = max(points)
        low, high = 0, max_point * m  # upper bound of the answer

        while low < high:
            mid = (low + high + 1) // 2
            if can_achieve(mid):
                low = mid
            else:
                high = mid - 1

        return low

