class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        # total area of all squares
        total = 0.0
        min_y = float('inf')
        max_y = -float('inf')
        for x, y, l in squares:
            total += l * l
            if y < min_y:
                min_y = y
            if y + l > max_y:
                max_y = y + l

        half = total / 2.0

        # helper: area below a horizontal line at height h
        def area_below(h: float) -> float:
            s = 0.0
            for _, y, l in squares:
                # height of the part of the square that lies below h
                if h <= y:
                    continue                      # completely above the line
                elif h >= y + l:
                    s += l * l                    # completely below the line
                else:
                    s += l * (h - y)              # partially covered
            return s

        lo, hi = min_y, max_y
        for _ in range(100):   # enough for 1e-9 precision
            mid = (lo + hi) / 2.0
            if area_below(mid) < half:
                lo = mid
            else:
                hi = mid
        return (lo + hi) / 2.0

