    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        candidates = []
        for row, lim in zip(grid, limits):
            if lim <= 0:
                continue
            # take up to lim largest elements from the row
            # sorting descending
            sorted_row = sorted(row, reverse=True)
            candidates.extend(sorted_row[:min(lim, len(row))])
