class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp maps (parity, alternating_sum) -> set of reachable products (non‑empty subsequences)
        dp: Dict[Tuple[int, int], Set[int]] = {}
        for num in nums:
            new_dp = {key: set(vals) for key, vals in dp.items()}   # copy for the "skip" case

            # start a new subsequence with the current number alone
            if num <= limit:
                key = (1, num)          # after taking one element, next index parity is 1 (odd)
                new_dp.setdefault(key, set()).add(num)

            # extend existing subsequences
            for (par, s), prods in dp.items():
                for p in prods:
                    new_par = 1 - par
                    new_sum = s + (num if par == 0 else -num)
                    new_prod = p * num
                    if new_prod <= limit:
                        key = (new_par, new_sum)
                        new_dp.setdefault(key, set()).add(new_prod)

            dp = new_dp

        # gather all products that give the required alternating sum k (parity does not matter)
        best = -1
        for parity in (0, 1):
            products = dp.get((parity, k))
            if products:
                cand = max(products)
                if cand > best:
                    best = cand
        return best

