class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        # ---------- build trie ----------
        # each node: {'cnt': int, 'next': dict(char->node_index), 'depth': int}
        nodes = [{'cnt': 0, 'next': {}, 'depth': 0}]   # root at index 0
        for w in words:
            cur = 0
            for ch in w:
                nxt = nodes[cur]['next'].get(ch)
                if nxt is None:
                    nodes.append({'cnt': 0, 'next': {}, 'depth': nodes[cur]['depth'] + 1})
                    nxt = len(nodes) - 1
                    nodes[cur]['next'][ch] = nxt
                cur = nxt
                nodes[cur]['cnt'] += 1

        # ---------- analyse nodes ----------
        L1 = 0                      # max depth where cnt >= k+1
        list_k = []                 # (depth, node_index) where cnt == k
        for idx, nd in enumerate(nodes):
            if nd['cnt'] >= k + 1:
                if nd['depth'] > L1:
                    L1 = nd['depth']
            elif nd['cnt'] == k:
                if nd['depth'] > 0:          # ignore root (depth 0)
                    list_k.append((nd['depth'], idx))

        # sort cnt==k nodes by depth descending
        list_k.sort(reverse=True)

        # ---------- answer each word ----------
        ans = [0] * len(words)
        for i, w in enumerate(words):
            cur = 0
            # collect node indices on the path whose cnt == k
            bad_nodes = set()
            for ch in w:
                cur = nodes[cur]['next'][ch]
                if nodes[cur]['cnt'] == k:
                    bad_nodes.add(cur)

            best = L1
            for depth, nd_idx in list_k:
                if nd_idx not in bad_nodes:
                    if depth > best:
                        best = depth
                    break   # deepest acceptable found
            ans[i] = best

        return ans

