class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        n = len(original)
        # prefix differences of original
        prefix = [0] * n
        for i in range(1, n):
            prefix[i] = prefix[i - 1] + (original[i] - original[i - 1])

        # Determine feasible interval for copy[0]
        lo = -10**18  # effectively -infinity
        hi = 10**18   # effectively +infinity
        for i in range(n):
            cur_lo = bounds[i][0] - prefix[i]
            cur_hi = bounds[i][1] - prefix[i]
            if cur_lo > lo:
                lo = cur_lo
            if cur_hi < hi:
                hi = cur_hi

        if lo > hi:
            return 0
        return hi - lo + 1

