class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        # distance on circular alphabet
        def dist(a: str, b: str) -> int:
            d = (ord(a) - ord(b)) % 26
            return d if d <= 13 else 26 - d   # min forward / backward

        # dp[l][r][c]  = max length inside s[l..r] using exactly c ops
        # initialise with -1 (impossible)
        dp: List[List[List[int]]] = [
            [[-1] * (k + 1) for _ in range(n)] for _ in range(n)
        ]

        # substrings of length 1
        for i in range(n):
            for c in range(k + 1):
                dp[i][i][c] = 1

        # increasing length
        for length in range(2, n + 1):
            for l in range(0, n - length + 1):
                r = l + length - 1
                for c in range(k + 1):
                    best = -1

                    # skip left character
                    best = max(best, dp[l + 1][r][c] if l + 1 <= r else 0)

                    # skip right character
                    best = max(best, dp[l][r - 1][c] if l <= r - 1 else 0)

                    # use both as a pair
                    cost = dist(s[l], s[r])
                    if c >= cost:
                        if l + 1 <= r - 1:
                            inner = dp[l + 1][r - 1][c - cost]
                        else:
                            inner = 0          # empty inner substring
                        if inner != -1:
                            best = max(best, 2 + inner)

                    dp[l][r][c] = best

        # answer = best length with total cost ≤ k
        return max(dp[0][n - 1][c] for c in range(k + 1) if dp[0][n - 1][c] != -1)

