class Solution:
    def maxSum(self, nums: List[int]) -> int:
        # Sum of all distinct positive numbers (including zero, which doesn't affect sum)
        positive_unique_sum = sum({x for x in nums if x > 0})
        if positive_unique_sum > 0:
            return positive_unique_sum
        # If there is no positive number, we must pick at least one element.
        return max(nums)

