class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        # segment tree for maximum capacity in a range
        size = 1
        while size < n:
            size <<= 1
        seg = [0] * (2 * size)

        # build leaves
        for i in range(n):
            seg[size + i] = baskets[i]
        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[2 * i], seg[2 * i + 1])

        def update(idx: int) -> None:
            """ mark basket idx as used (capacity becomes -inf) """
            pos = size + idx
            seg[pos] = -10**18  # smaller than any fruit quantity
            pos //= 2
            while pos:
                seg[pos] = max(seg[2 * pos], seg[2 * pos + 1])
                pos //= 2

        def find_first(node: int, l: int, r: int, need: int) -> int:
            """ return leftmost index in [l, r] with capacity >= need, assume seg[node] >= need """
            if l == r:
                return l
            mid = (l + r) // 2
            if seg[2 * node] >= need:
                return find_first(2 * node, l, mid, need)
            else:
                return find_first(2 * node + 1, mid + 1, r, need)

        unplaced = 0
        for qty in fruits:
            if seg[1] < qty:          # no basket can hold this fruit
                unplaced += 1
                continue
            idx = find_first(1, 0, size - 1, qty)
            # idx might be >= n (extra padded leaves); they have capacity 0, but seg[1] >= qty ensures idx < n
            update(idx)

        return unplaced

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        max_len = 0
        ns, nt = len(s), len(t)

        # all substrings of s (including empty)
        for i in range(ns + 1):
            for j in range(i, ns + 1):
                sub_s = s[i:j]
                # all substrings of t (including empty)
                for k in range(nt + 1):
                    for l in range(k, nt + 1):
                        sub_t = t[k:l]
                        combined = sub_s + sub_t
                        if combined == combined[::-1]:
                            cur_len = len(combined)
                            if cur_len > max_len:
                                max_len = cur_len
        return max_len

