class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        max_target = max(nums) if nums else 0

        # If already zero array
        if all(v == 0 for v in nums):
            return 0

        # reachable[i] is a bitset (int) where bit s is 1 if sum s can be formed for index i
        reachable = [(1 << 0) for _ in range(n)]          # only sum 0 is reachable initially
        mask_limit = (1 << (max_target + 1)) - 1          # keep bits only up to max_target

        for k, (l, r, val) in enumerate(queries, start=1):
            shift = val
            for i in range(l, r + 1):
                # add this value as an optional coin for index i
                reachable[i] |= (reachable[i] << shift) & mask_limit

            # after this query, check if all targets are reachable
            ok = True
            for i in range(n):
                if not (reachable[i] >> nums[i]) & 1:
                    ok = False
                    break
            if ok:
                return k

        return -1

