from typing import List

class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        freq = Counter(digits)
        results = set()

        def backtrack(pos: int, cur: int):
            if pos == 3:
                # last digit already ensured even
                results.add(cur)
                return
            for d in range(10):
                if freq[d] == 0:
                    continue
                if pos == 0 and d == 0:        # leading zero not allowed
                    continue
                if pos == 2 and d % 2 == 1:    # unit's place must be even
                    continue
                freq[d] -= 1
                backtrack(pos + 1, cur * 10 + d)
                freq[d] += 1

        backtrack(0, 0)
        return len(results)

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def is_beautiful(x: int) -> bool:
            s = 0
            p = 1
            while x:
                d = x % 10
                s += d
                p *= d
                if d == 0:          # product becomes 0, always divisible
                    return True
                x //= 10
            return p % s == 0

        cnt = 0
        for num in range(l, r + 1):
            if is_beautiful(num):
                cnt += 1
        return cnt

