class DSU:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.components = n

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x: int, y: int) -> None:
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return
        if self.rank[rx] < self.rank[ry]:
            rx, ry = ry, rx
        self.parent[ry] = rx
        if self.rank[rx] == self.rank[ry]:
            self.rank[rx] += 1
        self.components -= 1


class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        if n == 0:
            return 0

        # Pre‑compute distinct value sets for each row
        sets = [set(row) for row in properties]

        dsu = DSU(n)

        for i in range(n):
            si = sets[i]
            for j in range(i + 1, n):
                # quick reject if possible: the maximum possible intersection size
                # is the size of the smaller set
                if min(len(si), len(sets[j])) < k:
                    continue
                if len(si & sets[j]) >= k:
                    dsu.union(i, j)

        return dsu.components

class Solution:
    def reverseDegree(self, s: str) -> int:
        total = 0
        for idx, ch in enumerate(s, start=1):
            rev_pos = ord('z') - ord(ch) + 1  # 'a' -> 26, ..., 'z' -> 1
            total += rev_pos * idx
        return total

class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        # Maximum containers that can fit on the deck
        capacity = n * n
        # Maximum containers allowed by weight limit
        weight_limit = maxWeight // w
        return min(capacity, weight_limit)

