def count_snake_upto(x: int) -> int:
    if x < 10:
        return 0
    digits = list(map(int, str(x)))
    n = len(digits)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos: int, tight: bool, started: bool, msd: int, max_other: int, cnt: int) -> int:
        if pos == n:
            # valid only if number has at least two digits and condition holds
            return int(started and cnt >= 2 and msd > max_other)
        limit = digits[pos] if tight else 9
        total = 0
        for d in range(0, limit + 1):
            ntight = tight and (d == limit)
            if not started:
                if d == 0:
                    total += dp(pos + 1, ntight, False, -1, 0, 0)
                else:
                    total += dp(pos + 1, ntight, True, d, 0, 1)
            else:
                ncnt = cnt + 1
                nmax = max(max_other, d)
                total += dp(pos + 1, ntight, True, msd, nmax, ncnt)
        return total

    return dp(0, True, False, -1, 0, 0)

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    L, R = map(int, data)
    ans = count_snake_upto(R) - count_snake_upto(L - 1)
    print(ans)

