import sys

def feasible(K, A, N):
    """return True iff we can make K pairs using the rule 2*top <= bottom"""
    i = 0               # index among the K smallest (tops)
    j = N - K           # first index among the K largest (bottom candidates)
    while i < K and j < N:
        if 2 * A[i] <= A[j]:
            i += 1
            j += 1
        else:
            j += 1
    return i == K

