import sys

def compute_dp(items, X):
    dp = [-1] * (X + 1)
    dp[0] = 0
    for a, c in items:
        for cal in range(X, c - 1, -1):
            if dp[cal - c] != -1:
                val = dp[cal - c] + a
                if val > dp[cal]:
                    dp[cal] = val
    return dp

def min_calories(dp, target, X):
    # smallest calories c such that dp[c] >= target
    for c in range(X + 1):
        if dp[c] >= target:
            return c
    return X + 1  # impossible

