from collections import defaultdict

MOD = 998244353

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    M = int(data[1])
    S = data[2].strip()
    letters = [chr(ord('a') + i) for i in range(26)]

    zero_state = tuple([0] * (N + 1))
    cur = {zero_state: 1}

    # transition function
    def trans(state, ch):
        dp = list(state)
        ndp = [0] * (N + 1)
        ndp[0] = 0
        for i in range(1, N + 1):
            if S[i - 1] == ch:
                ndp[i] = dp[i - 1] + 1
            else:
                ndp[i] = dp[i] if dp[i] >= ndp[i - 1] else ndp[i - 1]
        return tuple(ndp)

    for _ in range(M):
        nxt = defaultdict(int)
        for st, cnt in cur.items():
            for ch in letters:
                ns = trans(st, ch)
                nxt[ns] = (nxt[ns] + cnt) % MOD
        cur = nxt

    ans = [0] * (N + 1)
    for st, cnt in cur.items():
        k = st[N]
        ans[k] = (ans[k] + cnt) % MOD

    print(' '.join(str(x) for x in ans))

