def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    dice_counts = []
    Ks = []
    sizes = []
    for _ in range(N):
        K = int(next(it))
        Ks.append(K)
        cnt = {}
        for _ in range(K):
            x = int(next(it))
            cnt[x] = cnt.get(x, 0) + 1
        dice_counts.append(cnt)
        sizes.append(len(cnt))

    max_prob = 0.0
    for i in range(N):
        cnt_i = dice_counts[i]
        Ki = Ks[i]
        for j in range(i + 1, N):
            cnt_j = dice_counts[j]
            Kj = Ks[j]
            # iterate over smaller dict for efficiency
            if sizes[i] <= sizes[j]:
                smaller, larger = cnt_i, cnt_j
            else:
                smaller, larger = cnt_j, cnt_i
            common = 0
            for val, c in smaller.items():
                cl = larger.get(val)
                if cl:
                    common += c * cl
            prob = common / (Ki * Kj)
            if prob > max_prob:
                max_prob = prob

    # output with enough precision
    print("{:.15f}".format(max_prob))

