def integer_cuberoot(n: int) -> int:
    """largest integer r such that r**3 <= n (n >= 0)"""
    if n < 0:
        raise ValueError("n must be non‑negative")
    # initial guess using float, safe for n <= 1e18
    r = int(round(n ** (1.0 / 3.0)))
    # adjust because of possible rounding errors
    while (r + 1) ** 3 <= n:
        r += 1
    while r ** 3 > n:
        r -= 1
    return r

