class SegTree:
    def __init__(self, data):
        n = len(data)
        self.N = 1
        while self.N < n:
            self.N <<= 1
        self.size = self.N << 1
        self.seg = [-10**18] * self.size
        self.lz = [0] * self.size
        for i, v in enumerate(data):
            self.seg[self.N + i] = v
        for i in range(self.N - 1, 0, -1):
            self.seg[i] = max(self.seg[i << 1], self.seg[i << 1 | 1])

    def _push(self, idx):
        if self.lz[idx]:
            for child in (idx << 1, idx << 1 | 1):
                self.seg[child] += self.lz[idx]
                self.lz[child] += self.lz[idx]
            self.lz[idx] = 0

    def _add(self, l, r, val, idx, left, right):
        if r < left or right < l:
            return
        if l <= left and right <= r:
            self.seg[idx] += val
            self.lz[idx] += val
            return
        self._push(idx)
        mid = (left + right) >> 1
        self._add(l, r, val, idx << 1, left, mid)
        self._add(l, r, val, idx << 1 | 1, mid + 1, right)
        self.seg[idx] = max(self.seg[idx << 1], self.seg[idx << 1 | 1])

    def range_add(self, l, r, val):
        if l > r:
            return
        self._add(l, r, val, 1, 0, self.N - 1)

    def _max(self, l, r, idx, left, right):
        if r < left or right < l:
            return -10**18
        if l <= left and right <= r:
            return self.seg[idx]
        self._push(idx)
        mid = (left + right) >> 1
        return max(self._max(l, r, idx << 1, left, mid),
                   self._max(l, r, idx << 1 | 1, mid + 1, right))

    def range_max(self, l, r):
        if l > r:
            return -10**18
        return self._max(l, r, 1, 0, self.N - 1)


