def mat_mul(A, B, mod):
    n = len(A)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        Ri = res[i]
        for k in range(n):
            aik = Ai[k]
            if aik:
                Bk = B[k]
                mul = aik
                for j in range(n):
                    Ri[j] = (Ri[j] + mul * Bk[j]) % mod
    return res

def mat_pow(mat, exp, mod):
    n = len(mat)
    # identity matrix
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1 % mod
    base = [row[:] for row in mat]
    while exp:
        if exp & 1:
            result = mat_mul(result, base, mod)
        base = mat_mul(base, base, mod)
        exp >>= 1
    return result

