_limit = 100000
_primes = []
is_composite = [False] * (_limit + 1)
for i in range(2, _limit + 1):
    if not is_composite[i]:
        _primes.append(i)
        step = i
        start = i * i
        if start > _limit:
            continue
        for j in range(start, _limit + 1, step):
            is_composite[j] = True

def factorize(num: int):
    """return dict {prime: exponent} for num (num <= 1e12 typical)"""
    res = {}
    n = num
    for p in _primes:
        if p * p > n:
            break
        if n % p == 0:
            cnt = 0
            while n % p == 0:
                n //= p
                cnt += 1
            res[p] = cnt
    if n > 1:
        # n is prime (or product of two large primes, but for our uses n <= 1e9 or small k)
        res[n] = 1
    return res

