# ---------- Primitive root modulo prime ----------
def primitive_root(p: int, factor_q1):
    """return a primitive root modulo prime p, given distinct prime factors of p-1"""
    for g in range(2, p):
        for q in factor_q1:
            if pow(g, (p - 1) // q, p) == 1:
                break
        else:
            return

import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    A = list(map(int, data[1:]))

    # If all are already 1, trivially possible
    if all(x == 1 for x in A):
        print("Yes")
        return

    # Try both possibilities for R at position 1
    for R1 in (0, 1):
        dp_prev = [False, False]          # dp_prev[r] : possible state with R_{i-1}=r
        dp_prev[R1] = True                # i = 1, R_1 = R1

        # iterate positions i = 2 .. N
        for i in range(2, N + 1):
            dp_curr = [False, False]
            for prevR in (0, 1):
                if not dp_prev[prevR]:
                    continue
                for currR in (0, 1):
                    if prevR == 1 and currR == 1:   # adjacent Rs not allowed
                        continue
                    # check coverage for position i-1 (0‑based index i-2)
                    if A[i - 2] == 0 and not (prevR or currR):
                        continue
                    dp_curr[currR] = True
            dp_prev = dp_curr

        # After processing, dp_prev corresponds to R_N states
        for RN in (0, 1):
            if not dp_prev[RN]:
                continue
            # adjacency between position N and position 1 (cycle)
            if R1 == 1 and RN == 1:
                continue
            # coverage for position N (index N-1)
            if A[N - 1] == 0 and not (RN or R1):
                continue
            # all conditions satisfied
            print("Yes")
            return

    print("No")

