import itertools, collections

def all_trees(N):
    # generate all parent arrays P[2..N]
    for parents in itertools.product(*[range(1,i) for i in range(2,N+1)]):
        P = [0]*(N+1)
        for i,p in enumerate(parents, start=2):
            P[i]=p
        yield P

def prob_edge_on_path(N,u,v):
    cnt_total=0
    cnt_edge={}
    for P in all_trees(N):
        cnt_total+=1
        # build adjacency
        adj=[[] for _ in range(N+1)]
        for i in range(2,N+1):
            p=P[i]
            adj[i].append(p)
            adj[p].append(i)
        # find path
        parent=[0]*(N+1)
        depth=[0]*(N+1)
        def dfs(x,par):
            for y in adj[x]:
                if y==par: continue
                parent[y]=x
                depth[y]=depth[x]+1
                dfs(y,x)
        dfs(1,0)
        # lift to find path edges
        a,b=u,v
        while a!=b:
            if depth[a]>=depth[b]:
                edge=a
                cnt_edge[edge]=cnt_edge.get(edge,0)+1
                a=parent[a]
            else:
                edge=b
                cnt_edge[edge]=cnt_edge.get(edge,0)+1
                b=parent[b]
    probs={i:cnt_edge.get(i,0)/cnt_total for i in range(2,N+1)}
    return probs

