class SegNode:
    __slots__ = ('ls', 'maxR')
    def __init__(self):
        self.ls = []
        self.maxR = []

def build(node, l, r, Ls, Rs, tree):
    if l == r:
        leaf = SegNode()
        leaf.ls = [Ls[l]]
        leaf.maxR = [Rs[l]]
        tree[node] = leaf
        return
    mid = (l + r) // 2
    build(node * 2, l, mid, Ls, Rs, tree)
    build(node * 2 + 1, mid + 1, r, Ls, Rs, tree)
    left = tree[node * 2]
    right = tree[node * 2 + 1]
    merged = SegNode()
    i = j = 0
    while i < len(left.ls) and j < len(right.ls):
        if left.ls[i] <= right.ls[j]:
            merged.ls.append(left.ls[i])
            merged.maxR.append(left.maxR[i])
            i += 1
        else:
            merged.ls.append(right.ls[j])
            merged.maxR.append(right.maxR[j])
            j += 1
    while i < len(left.ls):
        merged.ls.append(left.ls[i])
        merged.maxR.append(left.maxR[i])
        i += 1
    while j < len(right.ls):
        merged.ls.append(right.ls[j])
        merged.maxR.append(right.maxR[j])
        j += 1
    # suffix max of R
    for k in range(len(merged.maxR) - 2, -1, -1):
        if merged.maxR[k + 1] > merged.maxR[k]:
            merged.maxR[k] = merged.maxR[k + 1]
    tree[node] = merged

def node_has(node, Llow, Lhigh, Rth):
    ls = node.ls
    if not ls:
        return False
    idx = bisect.bisect_right(ls, Llow)
    if idx == len(ls) or ls[idx] > Lhigh:
        return False
    return node.maxR[idx] > Rth

